// Общие шаги для тестов адреса (#8ffd6e26). Ничего не сохраняют.
// Подсказки адреса приходят из Google Places — ВНЕШНИЙ СЕРВИС (тесты с ними помечены @google-places).
import * as path from 'path';
import { expect, Page } from '@playwright/test';

/** Сессия admin (компания «test»), путь — от файла, чтобы не зависеть от cwd. */
export const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');

export const UNIT_PLACEHOLDER = 'Apt 5B / Unit 12';

/** EN-интерфейс: localStorage 'preferred-language' до загрузки страницы. */
export async function setEnglish(page: Page) {
  await page.addInitScript(() => {
    try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ }
  });
}

export const addressInput = (page: Page) => page.getByRole('textbox', { name: /^Address/ });
export const unitInput = (page: Page) => page.getByLabel('Unit/Apt', { exact: true });

/** New Job: открыть форму и раскрыть поля Unit/City/State/ZIP («Edit address details»). */
export async function openNewJobAddressDetails(page: Page) {
  await page.goto('/JobForm?action=new');
  await expect(addressInput(page)).toBeVisible();
  await page.getByRole('button', { name: 'Edit address details' }).click();
  await expect(unitInput(page)).toBeVisible();
}

/**
 * Ввести адрес посимвольно (как пользователь — автокомплит реагирует на ввод) и выбрать подсказку:
 * main — первая строка подсказки (точно), secondary — вторая строка (город, штат), чтобы выбрать нужную из похожих.
 */
export async function typeAndPickSuggestion(page: Page, typed: string, main: string, secondary: string) {
  const input = addressInput(page);
  await input.click();
  await input.pressSequentially(typed, { delay: 20 });
  const item = page
    .locator('div')
    .filter({ has: page.getByText(main, { exact: true }) })
    .filter({ hasText: secondary })
    .last();
  await expect(item).toBeVisible();
  await item.getByText(main, { exact: true }).click();
}
